### 9. Create Catalog page (Interactive)
Create `Components/Pages/Catalog.razor`:

```razor
@page "/catalog"
@rendermode InteractiveServer
@inject CourseService CourseService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search courses, instructors..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartment">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
    </div>
</div>

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted mb-3">Showing @filteredCourses.Count course(s)</p>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in filteredCourses)
                {
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@course.DepartmentName</td>
                        <td>@course.Credits</td>
                        <td>@course.Instructor.Name</td>
                        <td>@course.Schedule</td>
                        <td>
                            <a href="course/@course.Id" class="btn btn-sm btn-primary">Details</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();
    private string searchTerm = "";
    private string selectedDepartment = "";

    [SupplyParameterFromQuery(Name = "dept")]
    public string? InitialDepartment { get; set; }

    protected override void OnInitialized()
    {
        departments = CourseService.GetDepartments();

        if (!string.IsNullOrEmpty(InitialDepartment))
            selectedDepartment = InitialDepartment;

        UpdateResults();
    }

    private string SearchTerm
    {
        get => searchTerm;
        set { searchTerm = value; UpdateResults(); }
    }

    private string SelectedDepartment
    {
        get => selectedDepartment;
        set { selectedDepartment = value; UpdateResults(); }
    }

    private void UpdateResults()
    {
        filteredCourses = CourseService.SearchCourses(searchTerm, selectedDepartment);
    }

    private void ClearFilters()
    {
        searchTerm = "";
        selectedDepartment = "";
        UpdateResults();
    }
}
