 <PageTitle>Enrollment Request</PageTitle>

 <h1>Enrollment Request</h1>

 @if (submitted)
 {
     <div class="alert alert-success">
         <h4 class="alert-heading">Enrollment Request Submitted!</h4>
         <p>Thank you, <strong>@Model!.StudentName</strong>. Your request to enroll in
             <strong>@(CourseService.GetCourse(Model!.CourseId)?.Title ?? "the selected course")</strong>
             has been received.</p>
         <p>Your student ID: <strong>@Model!.StudentId</strong></p>
         <hr />
         <p class="mb-0">You will receive a confirmation email within 2 business days.</p>
     </div>
     <a href="catalog" class="btn btn-primary">Browse More Courses</a>
     <a href="enroll" class="btn btn-outline-secondary ms-2">Submit Another</a>
 }
 else
 {
     <p>Fill out the form below to request enrollment in a course.</p>

     <form method="post" class="needs-validation" style="max-width: 600px;">
         <AntiforgeryToken />

         <div class="mb-3">
             <label for="studentName" class="form-label">Full Name</label>
             <input type="text" class="form-control" id="studentName" name="Model.StudentName"
                    value="@Model!.StudentName" required />
         </div>

         <div class="mb-3">
             <label for="studentId" class="form-label">Student ID</label>
             <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                    value="@Model!.StudentId" required placeholder="e.g., S12345678" />
         </div>

         <div class="mb-3">
             <label for="courseId" class="form-label">Course</label>
             <select class="form-select" id="courseId" name="Model.CourseId" required>
                 <option value="0">-- Select a course --</option>
                 @foreach (var course in courses)
                 {
                     @if (course.Id == Model!.CourseId)
                     {
                         <option value="@course.Id" selected>@course.Code — @course.Title (@course.CurrentEnrollment/@course.MaxEnrollment enrolled)</option>
                     }
                     else
                     {
                         <option value="@course.Id">@course.Code — @course.Title (@course.CurrentEnrollment/@course.MaxEnrollment enrolled)</option>
                     }
                 }
             </select>
         </div>

         <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
         <a href="catalog" class="btn btn-outline-secondary ms-2">Cancel</a>
     </form>
 }

 @code {
     [SupplyParameterFromForm]
     public EnrollmentRequest? Model { get; set; }

     [SupplyParameterFromQuery(Name = "courseId")]
     public int? PreselectedCourseId { get; set; }

     [CascadingParameter]
     public HttpContext? HttpContext { get; set; }

     private List<Course> courses = new();
     private bool submitted;

     protected override void OnInitialized()
     {
         Model ??= new();
         courses = CourseService.GetAllCourses();

         if (HttpContext != null && HttpMethods.IsPost(HttpContext.Request.Method))
         {
             if (!string.IsNullOrWhiteSpace(Model.StudentName) &&
                 !string.IsNullOrWhiteSpace(Model.StudentId) &&
                 Model.CourseId > 0)
             {
                 CourseService.SubmitEnrollment(Model);
                 submitted = true;
             }
         }
         else if (PreselectedCourseId.HasValue)
         {
             Model.CourseId = PreselectedCourseId.Value;
         }
     }
 }

